  const testName = "SAST: parse valid Semgrep JSON output";
  try {
    const semgrepOutput = JSON.stringify({
      results: [
        {
          check_id: "javascript.lang.security.audit.unsafe-regex.unsafe-regex",
          path: "test/file.js",
          start: { line: 42 },
          extra: {
            message: "Potential ReDoS vulnerability detected",
